"""Configuration, checkpoint I/O and classifier reconstruction."""
import json
from pathlib import Path

import torch

from .heads import ContinualLinear


def read_json(path):
    return json.loads(Path(path).read_text())


def write_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2) + '\n')


def load_checkpoint(path):
    # Checkpoints generated by this training run include class statistics and RNGs.
    return torch.load(path, map_location='cpu', weights_only=False)


def setup(config, device):
    torch.set_num_threads(int(config.get('cpu_threads', 4)))
    torch.backends.cuda.matmul.allow_tf32 = True
    torch.backends.cudnn.allow_tf32 = True
    if torch.device(device).type == 'cuda':
        torch.cuda.set_device(device)


def head_from_state(state, device='cpu'):
    sizes = [state[f'heads.{i}.weight'].shape[0]
             for i in range(sum(k.startswith('heads.') for k in state))]
    head = ContinualLinear(state['heads.0.weight'].shape[1], sizes[0])
    for size in sizes[1:]:
        head.update(size, freeze_old=False)
    head.load_state_dict(state)
    return head.to(device).eval()


def cpu_state(module):
    return {k: v.detach().cpu().clone() for k, v in module.state_dict().items()}
